const key='evening-lounge-demo-v1';let store={books:[],notes:[],chats:[],style:'Gentle',reduced:false};try{const d=JSON.parse(localStorage.getItem(key));if(d&&Array.isArray(d.chats))store={...store,...(window.CaveState?CaveState.normalize(d):d)};}catch{}if(!['Gentle','Reflective','Practical'].includes(store.style))store.style='Gentle';
store.profile=store.profile||null;store.worlds=Array.isArray(store.worlds)?store.worlds:[];store.activeWorld=store.activeWorld||null;store.loggedIn=!!store.loggedIn;
store.selectedCompanion=store.selectedCompanion||store.worlds.find(w=>w.id===store.activeWorld)?.companion||'maya';store.connectionRole=store.connectionRole||'Reflection partner';store.presence=store.presence||'alone';store.worlds.forEach(w=>{w.vibe=['Cozy','Fresh','Futuristic','Calm'].includes(w.vibe)?w.vibe:'Calm';w.prompt=w.prompt||''});
store.worlds.forEach(w=>{w.companion=w.companion||store.selectedCompanion;w.presence=w.presence||store.presence;w.style=w.style||store.style;});
