function sendMessage(value){value=value.trim();if(!value)return;messages.push({role:'user',worldName:activeWorld().name,text:value});let reply;const round=messages.filter(m=>m.role==='user').length;const replies={Gentle:['It can be hard to leave a busy day behind. What part of today is still on your mind?','You can take your time with that. What would feel like a small kindness to yourself tonight?','Thanks for making room for that thought. Would you like to keep reflecting or take a quiet pause?'],Reflective:['What part of today keeps coming back to you?','What do you notice about the way that moment made you feel?','What would you like to carry forward from this reflection?'],Practical:['What is one thing from today that you would like to set aside for tonight?','What is one small step you could take tomorrow? You could write it down, then give yourself permission to pause.','Would a short breathing pause or a few minutes of a pattern game suit you now?']};reply=replies[store.style][(round-1)%3];messages.push({role:'ai',speakerName:companion().name,worldName:activeWorld().name,text:reply});draft='';render();$('.messages .bubble:last-child')?.classList.add('response-ready');$('#chat-input').focus()}
